import pprint


class StoryOutlineRevision:
    """
    Represents a single entry in the history of a story's outline, including details about the collaborator,
    the outline content, the revision number, and the story ID.
    """

    def __init__(
        self,
        collaborator_user_id: Optional[str] = None,
        outline_content: Optional[str] = None,
        revision_number: Optional[int] = None,
        story_identifier: Optional[str] = None
    ):
        """
        Initialize a new instance of StoryOutlineRevision.

        :param collaborator_user_id: Unique identifier for the user who made the revision.
        :param outline_content: The content of the story outline at this revision.
        :param revision_number: The sequential number of this revision.
        :param story_identifier: Unique identifier for the story.
        """
        self._collaborator_user_id = collaborator_user_id
        self._outline_content = outline_content
        self._revision_number = revision_number
        self._story_identifier = story_identifier

    @property
    def collaborator_user_id(self) -> Optional[str]:
        """Get the unique identifier for the user who made the revision."""
        return self._collaborator_user_id

    @collaborator_user_id.setter
    def collaborator_user_id(self, value: str):
        """Set the unique identifier for the user who made the revision."""
        self._collaborator_user_id = value

    @property
    def outline_content(self) -> Optional[str]:
        """Get the content of the story outline at this revision."""
        return self._outline_content

    @outline_content.setter
    def outline_content(self, value: str):
        """Set the content of the story outline at this revision."""
        self._outline_content = value

    @property
    def revision_number(self) -> Optional[int]:
        """Get the sequential number of this revision."""
        return self._revision_number

    @revision_number.setter
    def revision_number(self, value: int):
        """Set the sequential number of this revision."""
        self._revision_number = value

    @property
    def story_identifier(self) -> Optional[str]:
        """Get the unique identifier for the story."""
        return self._story_identifier

    @story_identifier.setter
    def story_identifier(self, value: str):
        """Set the unique identifier for the story."""
        self._story_identifier = value

    def to_dict(self) -> dict:
        """Convert the object to a dictionary."""
        return {
            "collaborator_user_id": self._collaborator_user_id,
            "outline_content": self._outline_content,
            "revision_number": self._revision_number,
            "story_identifier": self._story_identifier
        }

    def __str__(self) -> str:
        """Return the string representation of the model."""
        return pprint.pformat(self.to_dict())

    def __repr__(self) -> str:
        """For `print` and `pprint`."""
        return self.__str__()

    def __eq__(self, other) -> bool:
        """Return true if both objects are equal."""
        if not isinstance(other, StoryOutlineRevision):
            return False
        return self.to_dict() == other.to_dict()

    def __ne__(self, other) -> bool:
        """Return true if both objects are not equal."""
        return not self == other


