import attr
from typing import Dict, Any, Generator, Optional

# Mock implementations for demonstration purposes
def get_event_date(event: Dict[str, Any]) -> Optional[str]:
    """Extract the date from the event."""
    return event.get('timestamp')

def get_event_recipient(event: Dict[str, Any]) -> Optional[str]:
    """Extract the recipient's email address from the event."""
    return event.get('recipient')

# Define the index functions mapping
INDEX_FUNCTIONS = {
    'date': get_event_date,
    'address': get_event_recipient
}

def index_single_event(event: Dict[str, Any], cache: Dict[str, Dict[str, Dict[str, Any]]]) -> None:
    """
    Index a single event into the cache based on predefined index functions.

    :param event: The event dictionary to be indexed.
    :param cache: The cache dictionary where events will be stored.
    """
    for index_name, index_function in INDEX_FUNCTIONS.items():
        key = index_function(event)
        if key is not None:
            index = cache.setdefault(index_name, {})
            index.setdefault(key, {})[event['id']] = event

def create_event_indexer(cache: Dict[str, Dict[str, Dict[str, Any]]]) -> Generator[None, Dict[str, Any], None]:
    """
    Create a generator to index mailgun events into a provided cache dictionary.

    :param cache: The cache dictionary where events will be stored.
    :yield: Yields control back to the caller after processing each event.
    """
    while True:
        try:
            event = yield
            index_single_event(event, cache)
        except GeneratorExit:
            break
        except Exception as e:
            print(f"Error processing event: {e}")

@attr.s
class MailgunEventIndexer:
    """
    A class to manage indexing of mailgun events.

    :ivar _cache: The internal cache dictionary to store indexed events.
    """
    _cache = attr.ib(default=attr.Factory(dict), repr=False)

    def start_indexing(self) -> Generator[None, Dict[str, Any], None]:
        """
        Start the indexing process and return the generator.

        :return: A generator that can be used to send events for indexing.
        """
        return create_event_indexer(self._cache)

    def __enter__(self) -> Generator[None, Dict[str, Any], None]:
        """
        Enter the context manager and start the indexing process.

        :return: A generator that can be used to send events for indexing.
        """
        return self.start_indexing()

    def __exit__(self, exc_type, exc_value, traceback) -> None:
        """
        Exit the context manager.

        :param exc_type: The exception type if an exception occurred.
        :param exc_value: The exception instance if an exception occurred.
        :param traceback: The traceback object if an exception occurred.
        """
        pass

