import time
import logging
import unittest
from unittest.mock import patch
from pysnmp.entity.rfc3413.oneliner import ntforg

# Mocking external dependencies to make the code self-contained
class MibResolver:
    def lookup_oid(self, oid: tuple) -> str:
        """Mock method to simulate OID lookup."""
        return f"OID-{oid}"

    def lookup(self, *args) -> str:
        """Mock method to simulate OID lookup with multiple arguments."""
        return f"OID-{args}"

class TrapReceiverThread:
    def __init__(self, config: dict, mibs: MibResolver, callback: callable):
        self.config = config
        self.mibs = mibs
        self.callback = callback
        self.running = False

    def start(self) -> None:
        """Simulate starting the trap receiver thread."""
        self.running = True
        # Simulate receiving a trap after a short delay
        time.sleep(1)
        self.callback({'oid': ('SNMPv2-MIB', 'coldStart'), 'arguments': {'sysName': "whatup"}})

    def stop(self) -> None:
        """Simulate stopping the trap receiver thread."""
        self.running = False

    def join(self) -> None:
        """Simulate joining the trap receiver thread."""
        pass

def configure_logging(logger: logging.Logger) -> None:
    """Configure the logger."""
    handler = logging.StreamHandler()
    formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
    handler.setFormatter(formatter)
    logger.addHandler(handler)
    logger.setLevel(logging.DEBUG)

def log_debug(message: str) -> None:
    """Log a debug message."""
    logger = logging.getLogger('sensu-trapd')
    logger.debug(message)

class TrapReceiverTestCase(unittest.TestCase):
    """
    Test case for the TrapReceiverThread class.
    """

    def setUp(self) -> None:
        """
        Set up the test environment.
        """
        self.config = {
            "snmp": {
                "transport": {
                    "listen_address": "127.0.0.1",
                    "listen_port": 1620,
                    "udp": {
                        "enabled": True
                    },
                    "tcp": {
                        "enabled": False
                    }
                },
                "auth": {
                    "version2": {
                        "community": "public",
                        "enabled": True
                    },
                    "version3": {
                        "enabled": True,
                        "users": {}
                    }
                }
            }
        }
        self.mibs = MibResolver()
        self.received_traps = []
        self.trap_receiver_thread = TrapReceiverThread(self.config, self.mibs, self.handle_received_trap)
        self.trap_receiver_thread.setDaemon(True)
        self.trap_receiver_thread.start()

    def tearDown(self) -> None:
        """
        Clean up after tests.
        """
        self.received_traps.clear()
        self.trap_receiver_thread.stop()
        self.trap_receiver_thread.join()

    def send_snmp_notification(self, notification_type: str, trap_oid: tuple, notification_args: dict = None) -> None:
        """
        Send an SNMP notification (trap or inform).

        :param notification_type: Type of notification ('trap' or 'inform').
        :param trap_oid: Tuple representing the trap OID.
        :param notification_args: Dictionary of additional arguments for the notification.
        """
        if notification_args is None:
            notification_args = {}

        agent_host: str = self.config['snmp']['transport']['listen_address']
        agent_port: int = self.config['snmp']['transport']['listen_port']
        community: str = self.config['snmp']['auth']['version2']['community']

        notifier = ntforg.NotificationOriginator()
        varbinds = [(ntforg.MibVariable(*var_name), value) for var_name, value in notification_args.items()]

        try:
            error = notifier.sendNotification(
                ntforg.CommunityData(community),
                ntforg.UdpTransportTarget((agent_host, agent_port)),
                notification_type,
                ntforg.MibVariable(*trap_oid),
                *varbinds
            )
            if error:
                raise Exception(f'Notification not sent: {error}')
        except Exception as e:
            self.fail(f'Failed to send notification: {e}')

        log_debug(f"Sent {notification_type}: {agent_host}:{agent_port} {trap_oid}")
        time.sleep(1)  # Simulate delay for race condition

    def handle_received_trap(self, trap: dict) -> None:
        """
        Handle received SNMP trap.

        :param trap: Dictionary containing trap details.
        """
        self.received_traps.append(trap)
        log_debug(f"Received Trap: {trap}")

    def assert_trap_received(self, expected_trap_oid: tuple, expected_args: dict = None) -> None:
        """
        Assert that a trap was received with the expected arguments.

        :param expected_trap_oid: Tuple representing the expected trap OID.
        :param expected_args: Dictionary of expected arguments for the trap.
        """
        if expected_args is None:
            expected_args = {}

        for trap in self.received_traps:
            if expected_trap_oid == self.mibs.lookup_oid(trap['oid']):
                for arg_type, expected_value in expected_args.items():
                    arg_oid = self.mibs.lookup(*arg_type)
                    self.assertIn(arg_oid, trap['arguments'])
                    self.assertEqual(trap['arguments'][arg_oid], expected_value)
                return

        self.fail("Trap not received (yet?)")

    def test_receive_trap(self) -> None:
        """
        Test receiving an SNMP trap.
        """
        self.send_snmp_notification('trap', ('SNMPv2-MIB', 'coldStart'), {('SNMPv2-MIB', 'sysName'): "whatup"})
        self.assert_trap_received(('SNMPv2-MIB', 'coldStart'), {('SNMPv2-MIB', 'sysName'): "whatup"})

